/**
 * @suppress
 */
public object FfiConverterTypePronoteClient: FfiConverter<PronoteClient, Long> {
    override fun lower(value: PronoteClient): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): PronoteClient {
        return PronoteClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): PronoteClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: PronoteClient) = 8UL

    override fun write(value: PronoteClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



