sealed class Exception: kotlin.Exception() {
    
    class InvalidCredentials(
        ) : Exception() {
        override val message
            get() = ""
    }
    
    class InvalidStartPage(
        ) : Exception() {
        override val message
            get() = ""
    }
    
    class Expired(
        ) : Exception() {
        override val message
            get() = ""
    }
    
    class UnsupportedClient(
        ) : Exception() {
        override val message
            get() = ""
    }
    
    class UnauthorizedTab(
        
        val v1: kotlin.ULong
        ) : Exception() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidAction(
        ) : Exception() {
        override val message
            get() = ""
    }
    
    class ConnectionFailed(
        ) : Exception() {
        override val message
            get() = ""
    }
    
    class Pronote(
        
        val `code`: kotlin.Long, 
        
        val `details`: kotlin.String
        ) : Exception() {
        override val message
            get() = "code=${ `code` }, details=${ `details` }"
    }
    
    class InvalidResponse(
        ) : Exception() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<Exception> {
        override fun lift(error_buf: RustBuffer.ByValue): Exception = FfiConverterTypeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeError : FfiConverterRustBuffer<Exception> {
    override fun read(buf: ByteBuffer): Exception {
        

        return when(buf.getInt()) {
            1 -> Exception.InvalidCredentials()
            2 -> Exception.InvalidStartPage()
            3 -> Exception.Expired()
            4 -> Exception.UnsupportedClient()
            5 -> Exception.UnauthorizedTab(
                FfiConverterULong.read(buf),
                )
            6 -> Exception.InvalidAction()
            7 -> Exception.ConnectionFailed()
            8 -> Exception.Pronote(
                FfiConverterLong.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> Exception.InvalidResponse()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Exception): ULong {
        return when(value) {
            is Exception.InvalidCredentials -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is Exception.InvalidStartPage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is Exception.Expired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is Exception.UnsupportedClient -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is Exception.UnauthorizedTab -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.v1)
            )
            is Exception.InvalidAction -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is Exception.ConnectionFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is Exception.Pronote -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterLong.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`details`)
            )
            is Exception.InvalidResponse -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: Exception, buf: ByteBuffer) {
        when(value) {
            is Exception.InvalidCredentials -> {
                buf.putInt(1)
                Unit
            }
            is Exception.InvalidStartPage -> {
                buf.putInt(2)
                Unit
            }
            is Exception.Expired -> {
                buf.putInt(3)
                Unit
            }
            is Exception.UnsupportedClient -> {
                buf.putInt(4)
                Unit
            }
            is Exception.UnauthorizedTab -> {
                buf.putInt(5)
                FfiConverterULong.write(value.v1, buf)
                Unit
            }
            is Exception.InvalidAction -> {
                buf.putInt(6)
                Unit
            }
            is Exception.ConnectionFailed -> {
                buf.putInt(7)
                Unit
            }
            is Exception.Pronote -> {
                buf.putInt(8)
                FfiConverterLong.write(value.`code`, buf)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is Exception.InvalidResponse -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



