public object FfiConverterSequenceSequenceTypeLesson: FfiConverterRustBuffer<List<List<Lesson>>> {
    override fun read(buf: ByteBuffer): List<List<Lesson>> {
        val len = buf.getInt()
        return List<List<Lesson>>(len) {
            FfiConverterSequenceTypeLesson.read(buf)
        }
    }

    override fun allocationSize(value: List<List<Lesson>>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterSequenceTypeLesson.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<List<Lesson>>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterSequenceTypeLesson.write(it, buf)
        }
    }
}









